-- ------------------------------------------------------------------ registrants (year 3+; not the system's suspensions, all earlier)
INSERT INTO registrations (id, event_id, user_id, dept, status, checked_in, checked_in_at, attend_via, food_allergy, dietary_pref, registered_at)
SELECT 105300 + ROW_NUMBER() OVER (ORDER BY u.id), 1053, u.id, u.dept,
       IF(u.id = 1011, 'absent', 'attended'),
       IF(u.id = 1011, 0, 1),
       IF(u.id = 1011, NULL, TIMESTAMP('2026-10-22', SEC_TO_TIME(16 * 3600 + 10 * 60 + (u.id % 25) * 60))),
       'onsite',
       CASE u.id WHEN 1003 THEN 'กุ้ง' WHEN 1015 THEN 'ถั่วลิสง' END,
       CASE u.id WHEN 1020 THEN 'มังสวิรัติ' END,
       TIMESTAMP('2026-10-05' + INTERVAL (u.id % 13) DAY, '18:40:00')
FROM users u
WHERE u.role = 'student'
  AND CAST(REGEXP_SUBSTR(u.dept, '[0-9]+') AS UNSIGNED) >= 3
  AND NOT EXISTS (SELECT 1 FROM blacklist_entries b WHERE b.user_id = u.id AND b.created_by IS NULL AND b.restored_at IS NULL);

INSERT INTO registration_checkins (registration_id, event_date, checked_in_at)
SELECT r.id, '2026-10-22', r.checked_in_at FROM registrations r WHERE r.event_id = 1053 AND r.checked_in = 1;

